            ["Переместить объект к вершине или ребру"] = "Move object to vertex or edge",
            ["Переместить к"] = "Move to",
            ["Переместить выбранный объект началом его рабочей системы координат к вершине или середине ребра другого объекта. Второй щелчок фиксирует положение. Ctrl — шаг сетки в метрах, Esc — отмена."] = "Move the selected object's working coordinate system origin to a vertex or edge midpoint on another object. Click again to place. Ctrl uses grid steps in metres. Esc cancels.",
            ["Укажите вершину или середину ребра"] = "Pick a vertex or edge midpoint",
            ["Укажите положение на ребре   •   Ctrl — шаг сетки"] = "Pick a point on the edge   •   Ctrl snaps to grid steps",
            ["   •   Esc — отмена"] = "   •   Esc cancels",
            ["Переместить объект по сплайну"] = "Move object along spline",
            ["Снять привязку к сплайну при перемещении"] = "Detach from spline when moved",
            ["Привязать к сплайну"] = "Attach to Spline",
            ["Отвязать от сплайна"] = "Detach from Spline",
            ["Траектория"] = "Path",
            ["Точек {0} · звеньев {1}"] = "Points {0} · links {1}",
            ["Радиус поворота слишком мал для этого сечения. Внутренняя сторона профиля складывается."] = "The bend is too tight for this cross-section. The inside of the profile folds over.",
            ["Перемещайте, поворачивайте и масштабируйте выделенные точки или звенья. Клавиши 1 и 2 меняют режим выделения."] = "Move, rotate or scale selected points or links. Press 1 or 2 to change selection mode.",
            ["Добавляйте точки щелчком. Escape завершает текущий штрих. Enter или повторный Escape закрывает инструмент."] = "Click to add points. Esc finishes the current stroke. Enter or a second Esc closes the tool.",
            ["Не построено частей: {0}. Поворот слишком резкий для выбранного сечения."] = "Skipped {0} pieces. The bend is too tight for this cross-section.",
            ["Выбранные точки ({0})"] = "Selected points ({0})",
            ["Крен сечения"] = "Section roll",
            ["Угол в градусах вокруг траектории в выбранных точках. Ноль сохраняет исходную ориентацию. Угол можно менять инструментом поворота в сцене."] = "Roll around the path in degrees at the selected points. Zero keeps the original orientation.",
            ["Рисовать сплайн"] = "Draw Spline",
            ["Удалить звено сплайна"] = "Delete spline link",
            ["Создать сплайн"] = "Create Spline",
            ["Сплайн"] = "Spline",
            ["Объект свободен. Чтобы привязать его к плану, выберите стену."] = "Not on a floor plan: pick a wall to put it on one.",
            ["Выбрать стену"] = "Pick Wall",
            ["Щёлкните по стене в окне сцены, чтобы привязать объект. Escape отменяет выбор."] = "Click a wall in the Scene view to put this on it; Escape cancels",
            ["Плоскость стены"] = "Face",
            ["Выбирает внешнюю, среднюю или внутреннюю плоскость стены."] = "On the wall's outside face, in its middle, or on its inside face.",
            ["Поворот, °"] = "Rotation",
            ["Углы относительно стены в градусах. При (0, 0, 0) объект направлен наружу от стены, его верх обращён вверх."] = "Relative to the wall: 0, 0, 0 faces out of it, up is up.",
            ["Повернуть объект на стене"] = "Rotate on wall",
            ["Развернуть"] = "Turn around",
            ["Развернуть объект на 180° вокруг вертикальной оси стены."] = "Turns the object 180 degrees about the wall's up axis.",
            ["Развернуть объект на стене"] = "Turn around on wall",
            ["Привязать к стене"] = "Attach to wall",
            ["Отвязать от стены"] = "Detach from wall",
            ["Переместить вдоль стены"] = "Move on wall",
            ["Переместить за пределы стены"] = "Move off wall",
            ["Сменить стену"] = "Choose wall",
            ["Крайние вершины ложатся на линии сетки, чтобы соседние браши стыковались без зазоров."] = "Snap outer vertices to grid lines so adjoining brushes meet without gaps.",
            ["По форме"] = "Shape",
            ["К сетке привязывается начало рабочей системы координат объекта, а форма перемещается вместе с ним."] = "Snap the working coordinate system origin to the grid and move the shape with it.",
            ["По началу WCS"] = "WCS origin",
            ["Положение и размеры сохраняют введённые значения без округления по сетке."] = "Keep the entered position and size without rounding to grid steps.",
            ["Внутри габарита координата по каждой оси лежит в диапазоне от 0 до 1. Начало рабочей системы координат объекта смещается при изменении размера."] = "Within the bounds, each axis ranges from 0 to 1. The WCS origin follows changes in size.",
            ["Доля размера"] = "Normalized",
            ["Расстояние от левого нижнего заднего угла. При изменении размера сохраняется в метрах."] = "Distance from the bottom-left back corner. Resizing preserves this distance in metres.",
            ["Расстояние"] = "Absolute",
            ["Материал вычитающего браша. Например, проём можно облицевать материалом дверной рамы."] = "Use the cutter's material, for example to line an opening with the door frame material.",
            ["Материал вычитающего браша"] = "Cutter material",
            ["Материал вырезаемого объёма. Например, внутренние поверхности проёма получают материал стены."] = "Use the material of the solid being cut, for example on the inside of a wall opening.",
            ["Материал вырезаемого объёма"] = "Cut solid material",
            ["Добавить"] = "Add",
            ["Вычесть"] = "Subtract",
            ["Твёрдое тело блокирует движение. Триггер посылает события при пересечении. В режиме «Нет» коллайдеры не создаются. Модуль браша может переопределить режим."] = "Solid geometry, a trigger volume, or no collider at all. A module on the brush (water, say) may override it.",
            ["Физический материал всех частей браша, включая триггеры. Задаёт трение и упругость, а также может использоваться для выбора звука."] = "On every collider piece of the brush, triggers included: friction and bounce, and a handle for sounds or other lookups.",
            ["Передавать данные о контактах частей браша в обработчики OnCollision."] = "The pieces provide contact data to OnCollision callbacks (Unity's Provide Contacts).",
            ["Габариты по осям X, Y и Z, в метрах."] = "Dimensions along X, Y and Z in metres.",
            ["Привязывает к сетке крайние вершины или начало рабочей системы координат объекта при перемещении и масштабировании. Поворот не вызывает привязку."] = "Snap outer vertices or the working coordinate system origin when moving or scaling. Rotation does not trigger snapping.",
            ["У блока или цилиндра остаются только стенки. При отключении весь объём сплошной."] = "Box and cylinder: keep only the walls.",
            ["Толщина стенок полого браша или пояса арки в метрах. Чем больше значение, тем меньше внутренний проём."] = "Hollow walls, and the thickness of an arch: metres.",
            ["Число граней цилиндра или конуса либо сегментов арки. Больше граней дают более гладкий контур. Минимум 3."] = "Cylinder and cone sides or arch segments. Minimum 3. Higher counts give a smoother outline.",
            ["Детализация сферы. При 1 граней меньше, при 5 поверхность наиболее гладкая."] = "Sphere: 1 is coarse, 5 is smooth.",
            ["Высота ступени в метрах, минимум 0,1 м. При фиксированной высоте лестницы увеличение уменьшает число ступеней."] = "Stairs: height of a step, metres, at least 0.1. The number of steps comes from the stairs' height.",
            ["Радиус внутренней колонны изогнутой или винтовой лестницы в метрах. При увеличении ступени располагаются дальше от оси."] = "Curved and spiral stairs: radius of the inner column the steps wrap around, metres.",
            ["Ширина ступени от внутренней колонны до внешнего края, в метрах. При увеличении лестница становится шире."] = "Curved and spiral stairs: width of the steps out from the column, metres.",
            ["Толщина каждой плиты ступени в метрах. Применяется к винтовой лестнице и лестнице без опоры под ступенями."] = "Spiral stairs, and stairs without support under the steps: thickness of each step slab, metres.",
            ["У прямой или изогнутой лестницы пространство под ступенями заполнено до пола. При отключении остаются отдельные плиты ступеней."] = "Linear and curved stairs: the steps stand on solid support down to the floor.",
            ["Размах изогнутой лестницы или арки в градусах. Чем больше угол, тем длиннее дуга. Для арки максимум 180°."] = "Curved stairs: total angle the steps cover; arch: the angle it spans, up to 180. Degrees.",
            ["Число ступеней изогнутой или винтовой лестницы. Минимум 1."] = "Number of steps on curved or spiral stairs. Minimum 1.",
            ["Число ступеней на полный оборот 360° винтовой лестницы. При увеличении угол между ступенями уменьшается. Минимум 1."] = "Steps per full turn of a spiral staircase. Minimum 1. More steps reduce the angle per step.",
            ["Поправка высоты первой ступени изогнутой или винтовой лестницы в метрах. Отрицательное число опускает её, 0 оставляет исходную высоту."] = "Curved and spiral stairs: extra height under the first step (negative lowers it), metres.",
            ["При взгляде сверху ступени идут против часовой стрелки. При отключении лестница закручивается по часовой стрелке."] = "When viewed from above, the stairs rise counterclockwise. Turn off to rise clockwise.",
            ["Верх винтовой лестницы образует наклонный пандус. При отключении верх остаётся ступенчатым."] = "Spiral stairs: the treads slope instead of stepping (a spiral ramp).",
            ["Нижняя поверхность винтовой лестницы образует непрерывный уклон. При отключении низ остаётся ступенчатым."] = "Spiral stairs: the underside slopes instead of stepping.",
            ["Материал всех граней браша. Его также можно перетащить на браш в окне сцены."] = "Applied to every face. Dropping a material onto the brush in the Scene view sets it too.",
            ["Для операции «Вычесть». Выбирает, получают срезы материал вычитающего браша или вырезаемого объёма."] = "Subtract only: the faces it cuts take this brush's material, or the material of the solid they were cut from.",
            ["Геометрия строится один раз. В игре группа перемещается целиком, например как лифт. Её браши становятся подвижными."] = "Built once and moved as a whole at runtime (a lift, a drawbridge): its brushes are not static.",
            ["Отбрасывать тени"] = "Cast shadows",
            ["Режим отбрасывания теней мешами группы."] = "How group meshes cast shadows.",
            ["Кэшировать статические тени"] = "Static shadow caster",
            ["Записывать тени в кэшированные карты теней один раз. Для статического освещения."] = "Write shadows to cached shadow maps once for static lighting.",
            ["Принимать тени"] = "Receive shadows",
            ["Отображать на мешах группы тени других объектов."] = "Show shadows from other objects on group meshes.",
            ["Глобальное освещение"] = "Global illumination",
            ["Источник глобального освещения статических мешей. Выберите карты освещения или световые пробы."] = "Choose lightmaps or light probes as the source of indirect lighting for static meshes.",
            ["Плотность карты освещения"] = "Scale in lightmap",
            ["Относительная плотность текселей карты освещения. При 2 плотность вдвое выше, при 0,5 вдвое ниже. При 0 меш участвует в расчёте освещения, но не занимает место в карте."] = "Relative lightmap texel density. 2 doubles the density, 0.5 halves it. At 0, the mesh contributes to lighting without taking lightmap space.",
            ["Ресурс параметров запекания. Пустое поле использует настройки сцены."] = "Baked lighting parameters. Leave empty to use the scene settings.",
            ["Жёсткий угол"] = "Hard angle",
            ["Порог в градусах. Более резкие рёбра разделяют острова UV. Уменьшение создаёт больше разрезов. Диапазон от 1° до 180°."] = "Edges sharper than this angle split UV charts. Smaller values create more seams. Range: 1°–180°.",
            ["Отклонение углов"] = "Angle error",
            ["Допустимое искажение углов на развёртке в процентах. Меньше — точнее углы, больше — свободнее раскладка. Диапазон от 1% до 75%."] = "Allowed UV angle distortion. Lower values preserve angles. Range: 1–75%.",
            ["Отклонение площади"] = "Area error",
            ["Допустимое искажение площади граней на развёртке в процентах. Уменьшение лучше сохраняет пропорции. Диапазон от 1% до 75%."] = "Allowed UV face area distortion. Lower values preserve proportions. Range: 1–75%.",
            ["Зазор между островами"] = "Pack margin",
            ["Расстояние между островами UV в пикселях для карты 1024 × 1024. Больше — меньше утечек света, но меньше места для граней. Диапазон от 1 до 64."] = "UV chart spacing in pixels at 1024 × 1024. Larger gaps reduce light bleeding at the cost of chart space. Range: 1–64.",
            ["Как меши получают освещение от световых проб при отсутствии карты освещения."] = "How meshes receive light probes when no lightmap is available.",
            ["Пробы отражений"] = "Reflection probes",
            ["Как меши используют пробы отражений."] = "How meshes use reflection probes.",
            ["Точка выборки проб"] = "Anchor override",
            ["Объект, задающий точку выборки проб. Пустое поле использует границы каждого меша."] = "Sample probes at this object's position. Leave empty to use each mesh's bounds.",
            ["Векторы движения"] = "Motion vectors",
            ["Режим расчёта векторов движения для размытия и временных эффектов."] = "Motion vectors used for motion blur and temporal effects.",
            ["Отсечение за преградами"] = "Dynamic occlusion",
            ["Скрывать меши за преградами, в том числе подвижные."] = "Hide meshes behind occluders, including moving meshes.",
            ["Слои рендеринга мешей для фильтрации света и декалей."] = "Mesh rendering layers used to filter lights and decals.",
            ["Вход в триггер"] = "On trigger enter",
            ["Событие при входе коллайдера в объём браша. Передаёт коллайдер, вошедший в объём."] = "Invoked when a collider enters the brush volume. Passes the collider that entered.",
            ["Выход из триггера"] = "On trigger exit",
            ["Событие при выходе коллайдера из объёма браша. Передаёт коллайдер, вышедший из объёма."] = "Invoked when a collider leaves the brush volume. Passes the collider that left.",
            ["Наружные стены строятся с внешней стороны линии. Линия совпадает с внутренней гранью стены."] = "Place exterior walls outside the line, with the inside face on the line.",
            ["Снаружи"] = "Outside",
            ["Осевая линия проходит посередине наружной стены."] = "Centre exterior walls on the drawn line.",
            ["По центру"] = "Centred",
            ["Наружные стены строятся с внутренней стороны линии."] = "Place exterior walls inside the drawn line.",
            ["Внутри"] = "Inside",
            ["Создавать пол"] = "Generate floor",
            ["Создавать потолок"] = "Generate ceiling",
            ["Своя высота, м"] = "Height override, m",
            ["Стены"] = "Walls",
            ["Открытые и внутренние, м"] = "Open and interior walls, m",
            ["Толщина отдельной стены, открытой ломаной и перегородки в метрах. Половина толщины по каждую сторону линии. Минимум 0,001 м. Своя толщина участка имеет приоритет."] = "Thickness of a single wall, open chain or partition in metres, centred on the line. Minimum 0.001 m. Segment overrides take precedence.",
            ["Наружный контур, м"] = "Outer boundary, m",
            ["Толщина наружной стены замкнутой комнаты в метрах. Минимум 0,001 м. Положение относительно линии задаётся ниже. Своя толщина участка имеет приоритет."] = "Exterior wall thickness of a closed room in metres. Minimum 0.001 m. Placement is set below. Segment overrides take precedence.",
            ["Высота по умолчанию, м"] = "Default height, m",
            ["Высота комнат и открытых стен от уровня плана, в метрах. Её можно переопределить у комнаты и участка стены. Минимум 0,001 м."] = "Room and open-wall height from the plan level in metres. Minimum 0.001 m. Rooms and wall segments may override it.",
            ["Положение наружной стены"] = "Exterior wall placement",
            ["Положение наружных стен относительно начерченной линии. Внутренние стены всегда центрируются на линии."] = "Position exterior walls relative to the drawn line. Interior walls are always centred on it.",
            ["Материал стен"] = "Wall material",
            ["Пол и потолок"] = "Floors and ceilings",
            ["Создавать плиту пола в каждой комнате. Для отдельной комнаты можно задать своё значение."] = "Generate a floor slab in each room. Individual rooms may override this setting.",
            ["Толщина пола, м"] = "Floor thickness, m",
            ["Толщина пола в метрах. Плита растёт вниз от основания стен."] = "Floor slab thickness in metres. The slab extends down from the wall base.",
            ["Создавать плиту потолка в каждой комнате. Для отдельной комнаты можно задать своё значение."] = "Generate a ceiling slab in each room. Individual rooms may override this setting.",
            ["Толщина потолка, м"] = "Ceiling thickness, m",
            ["Толщина потолка в метрах. Плита растёт вверх от верха стен."] = "Ceiling slab thickness in metres. The slab extends up from the top of the walls.",
            ["Название генератора. При повторном запуске он заменяет все браши внутри этого объекта."] = "What made these brushes; rebuilding it replaces everything inside this object.",
            ["Генератор"] = "Generator",
            ["Круг"] = "Circle",
            ["Круглый профиль для труб, колонн и тоннелей."] = "Round profile for pipes, columns and tunnels.",
            ["Прямоугольник"] = "Rectangle",
            ["Прямоугольный профиль для балок, дорог и стен. Половинный полый профиль образует открытый жёлоб."] = "Rectangular profile for beams, roads and walls. A hollow half profile forms an open channel.",
            ["Вертикально"] = "Upright",
            ["Верх профиля остаётся направлен вверх. Подходит для дорог, рельсов и ограждений."] = "Keep the top of the section facing up, for roads, rails and fences.",
            ["Вдоль траектории"] = "Follow path",
            ["Профиль поворачивается за траекторией без скручивания. Подходит для труб и направляющих."] = "Turn with the path without twisting, for pipes and guides.",
            ["Открытые"] = "Open",
            ["Полость открыта с обоих концов."] = "Leave the profile open at both ends.",
            ["Закрытые"] = "Capped",
            ["На концах профиля создаются заглушки."] = "Cap the open ends of the profile.",
            ["Скруглённые"] = "Rounded",
            ["Закрытые концы скругляются. Для круглого профиля создаётся полусфера, для плоского — полудиск."] = "Round the end caps. Circular sections get a hemisphere, flat sections a half disc.",
            ["Форма сечения"] = "Cross-section",
            ["Форма сечения, протягиваемого вдоль траектории."] = "Shape of the section swept along the path.",
            ["Размер сечения (м)"] = "Section size (m)",
